// Independent reverse-move DFS with incremental legality and dense memo slots.
// Input quads are generated by translated integer determinants in Python.
// Existing level files only provide memo addresses: every listed mask must be
// visited from the empty set, and every generated child must be listed.
#include <algorithm>
#include <array>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <string>
#include <vector>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
using U=uint64_t;
struct __attribute__((packed)) Value {U t=0,w=0;uint8_t g=0;};
struct Layer {
    int fd=-1;size_t count=0;const U* masks=nullptr;
    std::vector<Value> value;std::vector<uint8_t> done;
};
struct Solver {
    int v,K;U full;std::array<Layer,65> layer;std::vector<U> completion;
    uint64_t visited=0,edges=0;
    size_t key(int a,int b,int c)const{
        if(a>b)std::swap(a,b);if(b>c)std::swap(b,c);if(a>b)std::swap(a,b);
        return (a*v+b)*v+c;
    }
    U after(U s,U legal,int p)const{
        legal&=~(U(1)<<p);
        for(U x=s;x;x&=x-1){int a=__builtin_ctzll(x);
            for(U y=x&(x-1);y;y&=y-1)legal&=~completion[key(a,__builtin_ctzll(y),p)];}
        return legal;
    }
    Value solve(U s,U legal,int k){
        Layer& A=layer[k];auto ptr=std::lower_bound(A.masks,A.masks+A.count,s);
        if(ptr==A.masks+A.count||*ptr!=s){fprintf(stderr,"missing safe mask k=%d s=%llu\n",k,(unsigned long long)s);exit(7);}
        size_t id=ptr-A.masks;if(A.done[id])return A.value[id];
        Value result;
        if(!legal)result.t=result.w=U(1)<<k;
        else{
            U seen=0,all_t=0,all_w=~U(0),zero_t=0,zero_w=0;
            for(U x=legal;x;){int p=63-__builtin_clzll(x);x^=U(1)<<p;
                Value b=solve(s|(U(1)<<p),after(s,legal,p),k+1);++edges;
                seen|=U(1)<<b.g;all_t|=b.t;all_w&=b.w;
                if(!b.g){zero_t|=b.t;zero_w|=b.w;}}
            int g=0;while(seen&(U(1)<<g))++g;result.g=g;
            result.t=g?zero_t:all_t;result.w=g?zero_w:all_w;
        }
        if(!result.t||(result.w&~result.t))exit(8);
        U parity=(k+bool(result.g))%2?0xaaaaaaaaaaaaaaaaULL:0x5555555555555555ULL;
        if(result.t&~parity)exit(9);
        A.value[id]=result;A.done[id]=1;++visited;
        if(visited%10000000==0){fprintf(stderr,"verified DFS states=%llu\n",(unsigned long long)visited);fflush(stderr);}
        return result;
    }
};
int main(int argc,char** argv){
    if(argc!=4){fprintf(stderr,"usage: input_quads spilldir output.json\n");return 1;}
    Solver S;std::ifstream input(argv[1]);int nq;
    if(!(input>>S.v>>nq)||S.v>=64)return 2;
    S.full=(U(1)<<S.v)-1;S.completion.resize(S.v*S.v*S.v);
    for(int i=0;i<nq;++i){U q;input>>q;int p[4],j=0;for(U x=q;x;x&=x-1)p[j++]=__builtin_ctzll(x);if(j!=4)return 3;
        for(int skip=0;skip<4;++skip){int a[3],z=0;for(int r=0;r<4;++r)if(r!=skip)a[z++]=p[r];S.completion[S.key(a[0],a[1],a[2])]|=U(1)<<p[skip];}}
    uint64_t listed=0;
    for(int k=0;k<=64;++k){std::string path=std::string(argv[2])+"/level_"+std::to_string(k)+".occ";
        int fd=open(path.c_str(),O_RDONLY);if(fd<0){S.K=k-1;break;}
        struct stat st;if(fstat(fd,&st)||st.st_size%8)return 4;Layer& L=S.layer[k];L.fd=fd;L.count=st.st_size/8;
        L.masks=static_cast<const U*>(mmap(nullptr,st.st_size,PROT_READ,MAP_PRIVATE,fd,0));if(L.masks==MAP_FAILED)return 5;
        for(size_t i=0;i<L.count;++i)if(__builtin_popcountll(L.masks[i])!=k||(i&&L.masks[i-1]>=L.masks[i]))return 6;
        L.value.resize(L.count);L.done.resize(L.count);listed+=L.count;
    }
    S.solve(0,S.full,0);if(S.visited!=listed){fprintf(stderr,"unreachable masks\n");return 10;}
    FILE* out=fopen(argv[3],"w");if(!out)return 11;
    fprintf(out,"{\"vertices\":%d,\"quads\":%d,\"states\":%llu,\"edges\":%llu,\"levels\":[",S.v,nq,(unsigned long long)listed,(unsigned long long)S.edges);
    for(int k=0;k<=S.K;++k){Layer& L=S.layer[k];std::array<uint64_t,65> hist{};int maxg=0;U witness=0;
        for(size_t i=0;i<L.count;++i){Value b=L.value[i];++hist[b.g];if(b.g>maxg){maxg=b.g;witness=L.masks[i];}}
        fprintf(out,"%s{\"k\":%d,\"states\":%zu,\"max_g\":%d,\"max_witness\":%llu,\"histogram\":{",k?",":"",k,L.count,maxg,(unsigned long long)witness);
        bool first=true;for(int g=0;g<=64;++g)if(hist[g]){fprintf(out,"%s\"%d\":%llu",first?"":",",g,(unsigned long long)hist[g]);first=false;}fprintf(out,"}");
        if(k<=3){fprintf(out,",\"values\":[");for(size_t i=0;i<L.count;++i){Value b=L.value[i];fprintf(out,"%s[%llu,%u,%llu,%llu]",i?",":"",(unsigned long long)L.masks[i],b.g,(unsigned long long)b.t,(unsigned long long)b.w);}fprintf(out,"]");}
        fprintf(out,"}");
    }
    fprintf(out,"]}\n");fclose(out);fprintf(stderr,"complete verified=%llu edges=%llu\n",(unsigned long long)listed,(unsigned long long)S.edges);
}
